WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (489::BIGINT, 'Explica bien y lo repite las veces que sea necesario. Califica suave los exámenes y los quices también, que en ocasiones son en parejas, entonces también ayuda un montón. Incluso pueder hacer trabajos extra si el grupo va un poco mal. Las clases no son aburridas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'ae926a194f4cc4f1c4ea6c672c045b8b4631f5802159a9cd24369d0dc73f9f90'::TEXT, ARRAY[605]::BIGINT[]),
    (489::BIGINT, 'Si lleva con él desde mate general se le va a facilitar, es bastante difícil trabajar con él si no sabe como maneja las cosas. Es bastante colaborativo, pero tiene que mostrar interés'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Da crédito extra']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '638c02e5422e74b541e7a8f87e400b99945656ce2e794b0eed98dde1569a81e6'::TEXT, ARRAY[605]::BIGINT[]),
    (489::BIGINT, 'Muy buen profe, apoya mucho a los estudiantes e intenta ayudar al grupo si ve que va mal. :)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6ec3a59e8cd5febea3d6c442c4db43c9d84c6a5d6bc2c2cf4465034d396ebc02'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (489::BIGINT, 'Nunca entiendo nada, voy solo por tener fe de que la proxima clase va a explicar mejor. Me ha ayudado a hacer autodidacta, sin embargo, como profesor deja mucho que desear. CDI es rudo y necesario para el futuro de las carreras. Por lo que recomiendo, no matricular con él.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4b786a132208d9fe6e2a3493f246c4cd9bbabe6eaa76f46e944e99760c034816'::TEXT, ARRAY[605]::BIGINT[]),
    (489::BIGINT, 'Demasiado malo. Super aburrida las clases, explica demasiado rápido, lo único bueno que tiene, es que es medio accesible con los quices. De malo tiene un montón de cosas. Por favor, no matricule con él'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-28T00:00:00+00:00'::TIMESTAMPTZ, '5a56121baaae22e33a7cf696a9a4d5c6890668b4cff90b79c1653038ddb32c24'::TEXT, ARRAY[605]::BIGINT[]),
    (489::BIGINT, 'Explica muy rápido en temas importantes y en temas faciles explica de más. Las clases son muchas veces aburridas y ayuda con los quices pero casi no se le entiende nada. Se desvía demasiado de las clases y a veces es un poco antipático. No lo recomiendo para nada, si quiere pasar no matricule con él'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-15T00:00:00+00:00'::TIMESTAMPTZ, 'd44783834ce501c14aa527ba96de14f038253ff58dc8448b48fc010458db73b6'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Tiene una gentil personalidad, sin embargo se pierde muchísimo en clases, habla de temas que no tienen nada que ver con la materia y cuando quiere volver con la explicación hace más enredos de los que ya tenía. Ayuda con quices grupales o parejas así que busque bien con quien trabajar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, '444d8d2d8779e486967ca6f62329cba9f0a8159841acec5a46611c95a908736c'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'El profe se perdía mucho en clases pero califica suave, los quizzes eran fáciles porque los llega a hacer en pareja en ocasiones y eso ayuda mucho, también si el notaba que al grupo iba mal dejaba trabajos extras'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-19T00:00:00+00:00'::TIMESTAMPTZ, 'd50f9371a29fde14fe31a9604c254710b36190ed19b1356311efacf108582b34'::TEXT, ARRAY[634]::BIGINT[]),
    (489::BIGINT, 'Sus clases eran un poco dificiles de seguir y explica un poco raro'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'b0ccdabf9e250679392eab023a5519ea9eeb40ca5f95b7c06ec7db0e6ae48ac0'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Edward era la primera vez que daba Esta y se notaba, a cada rato se perdía o no le daba algo y se congelaba. Al inicio cuesta entenderle, pero la materia de Estadística es muy fácil y pronto le agarra el toque a la materia y al profe. No califica duro, le ayuda a uno más bien'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2026-01-20T00:00:00+00:00'::TIMESTAMPTZ, '5d57a6a285e356dfccb84fe85cadba3d0eab174b2f830f270a09c330cb13afe7'::TEXT, ARRAY[1057]::BIGINT[]),
    (489::BIGINT, 'El profe es bueno, aunque a veces se equivoca explicando la materia y eso lo hace un poco confuso. Se preocupa mucho porque uno entienda (atendiendo dudas y en las consultas), además ayuda muchísimo con sus quizes y tareas, califica suave así que 10/10.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2025-12-18T00:00:00+00:00'::TIMESTAMPTZ, '3d9b854183ca48f4c6ac733fc60ddda30a967d7791467f7026b9825ac443293f'::TEXT, ARRAY[634]::BIGINT[]),
    (489::BIGINT, 'Es muy buen profe, explica muy bien. Si tuviera que hacer las cosas mejor, iría a consulta cada que pueda. Los quices super bien la verdad, aveces en grupo y aveces como tareas. Creo que le hizo falta como enseñarnos un poquito más de modelado de funciones pero todo bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, '0bdde65cc9cb46107c93000d9da8249245d3ec583987e7e3e99861b6a4acdf78'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Si a usted le gusta canales como mate facil, Alex profe o el trad. de ingenieria, este profe le va a ser muy util, su forma de explicar es mas centrada en entender conceptos basicos para desarrollar, no tanto en esto es asi y se cabo. Vaya a las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9b905c97b83e1ca26bc3bdbc2d3857f498d08a5c48ae8749705e3f80c4bf1c31'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Los quiz son demasiado sencillos, muchas veces los hace en grupos o con cuaderno abierto, explica relativamente bien a que a veces va muy rápido, es muy sencillo ganar los puntos de quiz'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'e217dccc437ad2f83556c39c4852d3e03b85e2dce83432cfcae6b77a29d6aace'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Explica bastante bien, si tienen una duda el explica hasta que uno entienda, algunos quices deja que los alumnos decidan como se va a hacer o deja una actividad pequeña como quiz.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'd1fd3036a869fcb1eda94151197a582265642c37110e739bfc604ca731aa0041'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'El profe es simpático y a pesar de que no es asistencia obligatoria, no se pierdan clases. Los quizzes son sencillos y en grupo, varias veces se enreda mucho con la materia, así que si tienen una duda preguntennnnn'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-02T00:00:00+00:00'::TIMESTAMPTZ, '18531839c45688e2b0be697929ec67a81ef7a693cbfa55671925239a12b00aff'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'No es malo del todo, pero la clase es demasiado aburrida, se hace demasiado enredo a veces. Si usted tiene una duda se la trata de aclarar pero la vdd uno queda peor.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases largas']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '669aab82e4171a25cdccde19969ad3c04f658f1b318cd695652d2a49e3a82064'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Excelente profesor, realmente el como persona es todo un personaje y en plena clase se suelta algun facto historico de las matematicas que hacen que no sea tan plana la clase, evalua 10/10 y si usted tiene una duda el lo atiende de buena forma. Recomiendo no saltarse las clases con el.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd3116470efc0ff460476debc39901b16643e28f2a05d8eac43067cd33d1bd3ec'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'me parece un muy buen profesor. obvio hay q ponerle atención. constantemente pregunta si hay dudas y las aclara aunq sea muy tonta. buena gente. es justo a la hora de calificar. creo q si volvería a llevar clase con el'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Pocos exámenes']::TEXT[], '2025-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1849c1f10e2390115a403eb78632a6242db1c3c449e79a9d8702e75921cee10f'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Explica demasiado bien, recomendadisimo, con las evaluaciones la mayoría son quizzes en grupo o cosillas sencillas, la asistencia no es obligatoria pero si recomendaría no perderse las clases.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, '5ea9d17850f69d6e5462629c239a38c4bfc6d068f4e4a39ca165bf80b22bc8ec'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Es uno de los mejores profesores de mate que he tenido, explica muy bien y claramente y si no se le entiende algo con gusto te responderá las dudas que tengas. Siempre le agrega un poco de humor a sus clases, eso sin dejar de lado la exigencia que se necesita para pasar mate general. 100%recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-04-02T00:00:00+00:00'::TIMESTAMPTZ, '204f47abf0723cc21cac6a3e56f9585aa483369542ecc422dc0d2ad662760648'::TEXT, ARRAY[563]::BIGINT[]),
    (489::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-04T00:00:00+00:00'::TIMESTAMPTZ, '9bd4e98f99a081a07449256d16b6863675028b6eb020155694ee06f621e25bb9'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
